"use client"

import * as React from "react"
import { cn } from "cn"

import { Button } from "@/components/standard/button"

function CalendarSlider({
  className,
  days,
  value,
  defaultValue,
  onValueChange,
}: {
  className?: string
  days: { id: string; label: string; count?: number }[]
  value?: string
  defaultValue?: string
  onValueChange?: (id: string) => void
}) {
  const [uncontrolled, setUncontrolled] = React.useState(
    defaultValue ?? days[0]?.id
  )
  const selected = value ?? uncontrolled

  function select(id: string) {
    if (value === undefined) {
      setUncontrolled(id)
    }
    onValueChange?.(id)
  }

  return (
    <div
      data-slot="calendar-slider"
      className={cn("flex gap-1 overflow-x-auto", className)}
    >
      {days.map((day) => {
        const isOn = day.id === selected
        const tone = isOn ? "default" : "outline"

        return (
          <Button
            key={day.id}
            tone={tone}
            size="sm"
            className="min-w-12 flex-col gap-0 px-2"
            onClick={() => select(day.id)}
          >
            <span>{day.label}</span>
            {day.count !== undefined ? (
              <span className="text-[10px] opacity-80">{day.count}</span>
            ) : null}
          </Button>
        )
      })}
    </div>
  )
}

export { CalendarSlider }
